# consistency_test.jl — the cross-language consistency runner.
#
# `tests/consistency/cases.json` is the golden case set shared by every KCL
# language runner (python, nodejs, go, java, dotnet and now julia), generated by
# `tests/consistency/generate_cases.py`. Every runner reads the same manifest,
# calls the same RPCs through its own binding and asserts the same expectations,
# so a divergence between two bindings shows up as a failing case rather than as
# a difference nobody notices.
#
# The cases are hermetic: inline KCL source, or files inside the repository, so
# nothing here needs a registry, a network or a writable working directory.
#
# `runtests.jl` includes this file; the paths are derived from `@__DIR__` so the
# runner does not care what the working directory is.

# ---------------------------------------------------------------------------
# Manifest
# ---------------------------------------------------------------------------

"""The shared golden manifest, resolved from this file's location.

`Pkg.test` runs with the package root as the working directory, so the working
directory cannot be used to find a file that lives outside the package.
"""
const _CONSISTENCY_CASES_JSON =
    normpath(joinpath(@__DIR__, "..", "..", "tests", "consistency", "cases.json"))

"""
The repository root, i.e. the parent of the parent of the directory holding
`cases.json`. Manifest paths are pinned relative to it by
`generate_cases.py`.
"""
const _CONSISTENCY_REPO_ROOT = normpath(joinpath(_CONSISTENCY_CASES_JSON, "..", "..", ".."))

"""
Read the manifest, refusing to run against a version this runner does not know.

The manifest is read with the binding's own JSON reader (`KclLib._json_parse`),
so the runner adds no dependency to a package that deliberately ships with only
ProtoBuf.jl.
"""
function _consistency_cases()
    isfile(_CONSISTENCY_CASES_JSON) || error(
        "consistency manifest not found at $_CONSISTENCY_CASES_JSON; " *
        "run `python tests/consistency/generate_cases.py` to generate it")
    manifest = KclLib._json_parse(read(_CONSISTENCY_CASES_JSON, String))
    version = get(manifest, "version", nothing)
    version == 1 || error("unsupported consistency manifest version: $version")
    return manifest["cases"]
end

# ---------------------------------------------------------------------------
# Manifest JSON -> generated protobuf messages
# ---------------------------------------------------------------------------

# Manifest values are plain JSON: `String`, `Int64`/`Float64`, `Bool`,
# `nothing`, `Vector{Any}` and `Dict{String,Any}`. The generated structs want
# their own field types back, so every value is coerced against the type the
# field declares rather than against a hand-written list of argument names.

"""
    _consistency_message(T, data)

Build the generated protobuf message `T` from a manifest object. The generated
field table is the schema: each key the manifest carries that `T` declares is
coerced to that field's Julia type and passed by keyword, and anything else
falls back to the proto3 default. Reading the field table keeps a manifest that
gains new default-valued keys loadable.
"""
function _consistency_message(::Type{T}, data) where {T}
    data isa AbstractDict || return data
    kwargs = Pair{Symbol,Any}[]
    for name in fieldnames(T)
        key = String(name)
        haskey(data, key) || continue
        value = data[key]
        push!(kwargs, name => value === nothing ? nothing :
            _consistency_value(_unwrap(fieldtype(T, name)), value))
    end
    return T(; kwargs...)
end

# The generated structs spell an optional message field as `Union{Nothing,T}`
# and an explicit JSON `null` as `nothing`; the converter always works on the
# payload type.
_unwrap(::Type{T}) where {T} = T
_unwrap(::Type{Union{Nothing,T}}) where {T} = T

# `TestCaseInfo.duration` is a proto `uint64` that the manifest spells as a
# decimal string, so scalars are parsed when they arrive as text.
_consistency_value(::Type{T}, value) where {T} =
    value isa AbstractString ? parse(T, value) : T(value)
_consistency_value(::Type{String}, value) = String(value)
_consistency_value(::Type{Bool}, value) = Bool(value)
function _consistency_value(::Type{Vector{T}}, values) where {T}
    return T[_consistency_value(T, value) for value in values]
end
function _consistency_value(::Type{Dict{K,V}}, values::AbstractDict) where {K,V}
    return Dict{K,V}(convert(K, k) => _consistency_value(V, v) for (k, v) in values)
end
_consistency_value(::Type{T}, value::AbstractDict) where {T} = _consistency_message(T, value)

"""
    _consistency_request(rpc, args)

Manifest `args` for one RPC. `args.parse_args.paths` entries are pinned
repo-relative by `generate_cases.py`, so they are resolved against the
repository root before the runtime sees them — the core would not find the file
otherwise. Absolute entries are kept as-is.
"""
function _consistency_request(rpc::AbstractString, args)
    haskey(args, "parse_args") || return args
    node = args["parse_args"]
    resolved = copy(node)
    resolved["paths"] = String[_consistency_path(p) for p in get(node, "paths", Any[])]
    return merge(args, Dict("parse_args" => resolved))
end

_consistency_path(path::AbstractString) =
    isabspath(path) ? String(path) : normpath(joinpath(_CONSISTENCY_REPO_ROOT, path))

# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

# The RPC surface this runner knows how to drive: the manifest's `rpc` selects
# the generated request message and the binding's typed wrapper. The result
# message is not needed — `expect` is compared field by field through
# `getproperty`, so the cases stay decoupled from the result type.
const _CONSISTENCY_RPCS = Dict(
    "KclService.Ping" => (PingArgs, ping),
    "KclService.ExecProgram" => (ExecProgramArgs, exec_program),
    "KclService.FormatCode" => (FormatCodeArgs, format_code),
    "KclService.ValidateCode" => (ValidateCodeArgs, validate_code),
    "KclService.FormatTestReport" => (FormatTestReportArgs, format_test_report),
    "KclService.GenerateToml" => (GenerateTomlArgs, generate_toml),
    "KclService.GenerateKcl" => (GenerateKclArgs, generate_kcl),
    "KclService.GenerateOpenAPI" => (GenerateOpenAPIArgs, generate_openapi),
    "KclService.GenerateProto" => (GenerateProtoArgs, generate_proto),
    "KclService.GenerateDoc" => (GenerateDocArgs, generate_doc),
)

function _consistency_call(rpc::AbstractString, args)
    haskey(_CONSISTENCY_RPCS, rpc) || error("no consistency runner support for rpc $rpc")
    request_type, wrapper = _CONSISTENCY_RPCS[rpc]
    return wrapper(_consistency_message(request_type, args))
end

"""
The RPC surface of the loaded core, resolved once per run.

Cores that predate `BuiltinService.ListMethod` answer with an empty list, and a
dispatcher that does not know the RPC at all raises; either way the surface is
"unknown" and the `new_core` cases are skipped rather than failed.
"""
function _consistency_methods()
    try
        return Set{String}(list_method().method_name_list)
    catch
        return Set{String}()
    end
end

# ---------------------------------------------------------------------------
# Comparison
# ---------------------------------------------------------------------------

# `FormatCodeResult.formatted` is the proto `bytes` field, i.e. a
# `Vector{UInt8}`, while the manifest records it as a string.
_consistency_actual(value::Vector{UInt8}) = String(value)
_consistency_actual(value) = value

"""A line-wise `- expected` / `+ actual` dump of a mismatching field."""
function _consistency_diff(expected, actual)
    want = split(string(expected), '\n')
    got = split(string(actual), '\n')
    out = IOBuffer()
    println(out, "--- expected\n+++ actual")
    for i in 1:max(length(want), length(got))
        e = i <= length(want) ? want[i] : nothing
        a = i <= length(got) ? got[i] : nothing
        if e == a
            println(out, "  ", e)
        elseif e !== nothing && a !== nothing
            println(out, "- ", e, "\n+ ", a)
        else
            e === nothing || println(out, "- ", e)
            a === nothing || println(out, "+ ", a)
        end
    end
    return String(take!(out))
end

"""
    _consistency_case(case, methods)

Run one manifest case and assert every field its `expect` mentions. Fields the
case does not expect are not asserted, which keeps the manifest free to pin only
what is stable across cores.

Returns `true` when the case ran, `false` when it was skipped because the loaded
core does not expose the RPC.
"""
function _consistency_case(case, methods)::Bool
    name = case["name"]
    rpc = case["rpc"]
    if get(case, "new_core", false) && !(rpc in methods)
        @test_skip "core does not list $rpc (old core)"
        return false
    end
    result = _consistency_call(rpc, _consistency_request(rpc, case["args"]))
    for (field, expected) in case["expect"]
        actual = _consistency_actual(getproperty(result, Symbol(field)))
        if actual != expected
            # A field can be a whole OpenAPI document, so the line diff is the
            # only failure output worth reading.
            println(stderr, "consistency case `$name` field `$field` mismatch:\n",
                _consistency_diff(expected, actual))
        end
        @test actual == expected
    end
    return true
end

# Loaded once: the manifest is the contract, not a per-case fixture, and a
# missing or unversioned file must fail loudly rather than turn this suite into
# a silent no-op.
const _CONSISTENCY_CASES = _consistency_cases()

@testset "consistency" begin

    @testset "manifest" begin
        @test !isempty(_CONSISTENCY_CASES)
        @test all(c -> haskey(c, "name") && haskey(c, "rpc") && haskey(c, "expect"),
            _CONSISTENCY_CASES)
        # Every case must name an RPC this runner drives, otherwise the loop
        # below would fail on an unknown-rpc error instead of an assertion.
        @test all(c -> haskey(_CONSISTENCY_RPCS, c["rpc"]), _CONSISTENCY_CASES)
    end

    # `list_method` is consulted once: the answer is the same for every case and
    # the RPC surface cannot change mid-process.
    methods = _consistency_methods()
    skipped = String[]

    for case in _CONSISTENCY_CASES
        @testset "consistency: $(case["name"])" begin
            _consistency_case(case, methods) || push!(skipped, case["name"])
        end
    end

    @info string("consistency cases: ", length(_CONSISTENCY_CASES) - length(skipped),
        " run, ", length(skipped), " skipped",
        isempty(skipped) ? "" : " ($(join(skipped, ", ")))")
end
